/**
 * @method
 * @name hashkey#fetchTime
 * @description fetches the current integer timestamp in milliseconds from the exchange server
 * @see https://hashkeyglobal-apidoc.readme.io/reference/check-server-time
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {int} the current integer timestamp in milliseconds from the exchange server
 */
func (this *Hashkey) FetchTimeAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchTimeBody(ch, optionalArgs...)
	return ch
}
func (this *Hashkey) fetchTimeBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	params := GetArg(optionalArgs, 0, map[string]any{})
	_ = params

	response := (<-this.PublicGetApiV1Time(params))
	PanicOnError(response)

	//
	//     {
	//         "serverTime": 1721661553214
	//     }
	//
	ch <- this.SafeInteger(response, "serverTime")
	return nil
}

/**
 * @method
 * @name hashkey#fetchStatus
 * @description the latest known information on the availability of the exchange API
 * @see https://hashkeyglobal-apidoc.readme.io/reference/test-connectivity
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [status structure]{@link https://docs.ccxt.com/?id=exchange-status-structure}
 */
func (this *Hashkey) FetchStatusAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchStatusBody(ch, optionalArgs...)
	return ch
}
func (this *Hashkey) fetchStatusBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	params := GetArg(optionalArgs, 0, map[string]any{})
	_ = params

	response := (<-this.PublicGetApiV1Ping(params))
	PanicOnError(response)

	//
	// {}
	//
	ch <- map[string]any{
		"status":  "ok",
		"updated": nil,
		"eta":     nil,
		"url":     nil,
		"info":    response,
	}
	return nil
}

