func (this *Hashkey) ParseTrade(trade any, optionalArgs ...any) any {
	//
	// fetchTrades
	//
	//     {
	//         "t": 1721682745779,
	//         "p": "67835.99",
	//         "q": "0.00017",
	//         "ibm": true
	//     }
	//
	// fetchMyTrades spot
	//
	//     {
	//         "id": "1739352552862964736",
	//         "clientOrderId": "1722082982086472",
	//         "ticketId": "1739352552795029504",
	//         "symbol": "ETHUSDT",
	//         "symbolName": "ETHUSDT",
	//         "orderId": "1739352552762301440",
	//         "matchOrderId": "0",
	//         "price": "3289.96",
	//         "qty": "0.001",
	//         "commission": "0.0000012",
	//         "commissionAsset": "ETH",
	//         "time": "1722082982097",
	//         "isBuyer": true,
	//         "isMaker": false,
	//         "fee": {
	//             "feeCoinId": "ETH",
	//             "feeCoinName": "ETH",
	//             "fee": "0.0000012"
	//         },
	//         "feeCoinId": "ETH",
	//         "feeAmount": "0.0000012",
	//         "makerRebate": "0"
	//     }
	//
	// fetchMyTrades swap
	//     {
	//         "time": "1722429951648",
	//         "tradeId": "1742263144691139328",
	//         "orderId": "1742263144028363776",
	//         "symbol": "ETHUSDT-PERPETUAL",
	//         "price": "3327.54",
	//         "quantity": "4",
	//         "commissionAsset": "USDT",
	//         "commission": "0.00798609",
	//         "makerRebate": "0",
	//         "type": "LIMIT",
	//         "side": "BUY_OPEN",
	//         "realizedPnl": "0",
	//         "isMarker": false
	//     }
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var timestamp any = this.SafeInteger2(trade, "t", "time")
	var marketId any = this.SafeString(trade, "symbol")
	market = this.SafeMarket(marketId, market)
	var side any = this.SafeStringLower(trade, "side") // swap trades have side param
	if IsTrue(!IsEqual(side, nil)) {
		side = this.SafeString(Split(side, "_"), 0)
	}
	var isBuyer any = this.SafeBool(trade, "isBuyer")
	if IsTrue(!IsEqual(isBuyer, nil)) {
		side = Ternary(IsTrue(isBuyer), "buy", "sell")
	}
	var takerOrMaker any = nil
	var isMaker any = this.SafeBool2(trade, "isMaker", "isMarker")
	if IsTrue(!IsEqual(isMaker, nil)) {
		takerOrMaker = Ternary(IsTrue(isMaker), "maker", "taker")
	}
	var isBuyerMaker any = this.SafeBool(trade, "ibm")
	// if public trade
	if IsTrue(!IsEqual(isBuyerMaker, nil)) {
		takerOrMaker = "taker"
		side = Ternary(IsTrue(isBuyerMaker), "sell", "buy")
	}
	var feeCost any = this.SafeString(trade, "commission")
	var feeCurrncyId any = this.SafeString(trade, "commissionAsset")
	var feeInfo any = this.SafeDict(trade, "fee")
	var fee any = nil
	if IsTrue(!IsEqual(feeInfo, nil)) {
		feeCost = this.SafeString(feeInfo, "fee")
		feeCurrncyId = this.SafeString(feeInfo, "feeCoinId")
	}
	if IsTrue(!IsEqual(feeCost, nil)) {
		fee = map[string]any{
			"cost":     this.ParseNumber(feeCost),
			"currency": this.SafeCurrencyCode(feeCurrncyId),
		}
	}
	return this.SafeTrade(map[string]any{
		"id":           this.SafeString2(trade, "id", "tradeId"),
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       GetValue(market, "symbol"),
		"side":         side,
		"price":        this.SafeString2(trade, "p", "price"),
		"amount":       this.SafeStringN(trade, []any{"q", "qty", "quantity"}),
		"cost":         nil,
		"takerOrMaker": takerOrMaker,
		"type":         nil,
		"order":        this.SafeString(trade, "orderId"),
		"fee":          fee,
		"info":         trade,
	}, market)
}

